1	//! The gate in the factory (DECISIONS.md D20, D21). Every `sandbox::*` call a
2	//! turn makes reaches `judge` through a `pre-trigger` hook, and
3	//! `bastion_core::govern::gate` decides it. The hook reads the policy from
4	//! memory and hands every record to the audit writer, so a slow store never
5	//! stalls a turn. Without an audit writer it refuses every call.
6	
7	use bastion_protocol::Change;
8	use std::collections::HashMap;
9	use std::sync::{Arc, Mutex, RwLock};
10	
11	use bastion_core::Stage;
12	use bastion_core::audit;
13	use bastion_core::eval::Override;
14	use bastion_core::govern::{self, Call, Capability, Constraint, Decision, Verdict};
15	use serde_json::{Value, json};
16	
17	use crate::audit_log::AuditLog;
18	use crate::charter::{self, Charter};
19	use crate::engine::NS;
20	use crate::engine::{DEFAULT_NAMESPACE, Engine};
21	use crate::factory::{OnChange, now};
22	use crate::store::{HeldCall, Store};
23	
24	const RUN_MS: u64 = 120_000;
25	
26	/// The rules the gate judges by, as the store last gave them.
27	struct Policy {
28	    constraints: Vec<Constraint>,
29	    grants: Vec<Capability>,
30	}
31	
32	/// A rule's deterministic form (D55): the calls and words a word match
33	/// binds, or the hook command code runs before those calls.
34	#[derive(Default)]
35	pub struct Form {
36	    pub function: String,
37	    pub contains: String,
38	    pub hook: String,
39	}
40	
41	/// What a scope setting is for: a constraint by id, or a grant by its kind
42	/// and function.
43	pub enum Scoped<'a> {
44	    Constraint(&'a str),
45	    Grant(Stage, &'a str),
46	}
47	
48	pub struct Gate {
49	    store: Arc<dyn Store>,
50	    engine: Arc<dyn Engine>,
51	    on_change: OnChange,
52	    /// None until the first load. Until then every call is refused.
53	    policy: RwLock<Option<Policy>>,
54	    /// The writer, or why there is none (such as no Keychain key).
55	    audit: Result<Arc<AuditLog>, String>,
56	    /// Each job's charter, read from its worktree when a turn starts.
57	    charters: Mutex<HashMap<String, Arc<Charter>>>,
58	    /// Each job's repository hook runs, latest last.
59	    hook_runs: Mutex<HashMap<String, Vec<String>>>,
60	    /// What each job's latest review diff broke, by constraint.
61	    findings: Mutex<HashMap<String, Vec<String>>>,
62	    /// The rungs an eval's arm sets for each of its trial jobs.
63	    overrides: Mutex<HashMap<String, Vec<Override>>>,
64	    /// Each job's approved acceptance test files, which no turn may write.
65	    /// The job's stored runtime keeps them across a restart.
66	    approved: Mutex<HashMap<String, Vec<String>>>,
67	}
68	
69	/// The factory's rule for one approved acceptance test: enforced, so
70	/// a turn that writes it is refused.
71	fn approved_test(file: &str) -> Constraint {
72	    Constraint {
73	        id: format!("approved-test:{file}"),
74	        rule: format!("Do not change {file}: it is an approved acceptance test."),
75	        function: "sandbox::fs::write".into(),
76	        contains: format!("/work/repo/{file}"),
77	        rung: bastion_core::govern::Enforcement::Enforced,
78	        source: bastion_core::govern::Source::Owner,
79	        steps: vec![bastion_core::govern::EVERY.into()],
80	        hook: String::new(),
81	        reviewer: String::new(),
82	        capability: false,
83	    }
84	}
85	
86	/// What the rules read from a call: its command line in any of the shapes
87	/// `sandbox::exec` takes (`argv`, or `cmd` with `args`), else its path, and
88	/// what a write writes.
89	pub(crate) fn call_of(call: &Value) -> Call {
90	    let arguments = &call["arguments"];
91	    let words = |v: &Value| -> Vec<String> {
92	        v.as_array()
93	            .into_iter()
94	            .flatten()
95	            .filter_map(|w| w.as_str().map(String::from))
96	            .collect()
97	    };
98	    let mut line = words(&arguments["argv"]);
99	    if let Some(cmd) = arguments["cmd"].as_str() {
100	        line.push(cmd.into());
101	        line.extend(words(&arguments["args"]));
102	    }
103	    let text = if line.is_empty() {
104	        arguments["path"].as_str().unwrap_or_default().to_string()
105	    } else {
106	        line.join(" ")
107	    };
108	    Call {
109	        function: call["function_id"].as_str().unwrap_or_default().into(),
110	        text,
111	        content: arguments["content"].as_str().unwrap_or_default().into(),
112	    }
113	}
114	
115	/// A call's arguments as a hook reads `tool_input`.
116	fn tool_input(held: &HeldCall) -> Value {
117	    match held.call.function.as_str() {
118	        "sandbox::exec" => json!({ "command": held.call.text }),
119	        _ => json!({ "file_path": held.call.text, "content": held.arguments["content"] }),
120	    }
121	}
122	
123	fn text_result(text: &str, details: Value, is_error: bool) -> Value {
124	    json!({ "content": [{ "type": "text", "text": text }], "details": details, "is_error": is_error })
125	}
126	
127	/// A step that only reads (D42) may not write a file, whatever its kind's
128	/// grants allow.
129	fn reads_only(envelope: &Value, call: &Call, verdict: Verdict) -> Verdict {
130	    let narrowed = envelope["metadata"]["reads_only"] == true;

