/// What a scope setting is for: a constraint by id, or a grant by its kind
/// and function.
pub enum Scoped<'a> {
    Constraint(&'a str),
    Grant(Stage, &'a str),
}

pub struct Gate {
    store: Arc<dyn Store>,
    engine: Arc<dyn Engine>,
    on_change: OnChange,
    /// None until the first load. Until then every call is refused.
    policy: RwLock<Option<Policy>>,
    /// The writer, or why there is none (such as no Keychain key).
    audit: Result<Arc<AuditLog>, String>,
    /// Each job's charter, read from its worktree when a turn starts.
    charters: Mutex<HashMap<String, Arc<Charter>>>,
    /// Each job's repository hook runs, latest last.
    hook_runs: Mutex<HashMap<String, Vec<String>>>,
    /// What each job's latest review diff broke, by constraint.
    findings: Mutex<HashMap<String, Vec<String>>>,
    /// The rungs an eval's arm sets for each of its trial jobs.
    overrides: Mutex<HashMap<String, Vec<Override>>>,
    /// Each job's approved acceptance test files, which no turn may write.
    /// The job's stored runtime keeps them across a restart.
    approved: Mutex<HashMap<String, Vec<String>>>,
}

/// The factory's rule for one approved acceptance test: enforced, so
/// a turn that writes it is refused.
fn approved_test(file: &str) -> Constraint {
    Constraint {
        id: format!("approved-test:{file}"),
        rule: format!("Do not change {file}: it is an approved acceptance test."),
        function: "sandbox::fs::write".into(),
        contains: format!("/work/repo/{file}"),
        rung: bastion_core::govern::Enforcement::Enforced,
        source: bastion_core::govern::Source::Owner,
        steps: vec![bastion_core::govern::EVERY.into()],
        hook: String::new(),
        reviewer: String::new(),
        capability: false,
    }
}

/// What the rules read from a call: its command line in any of the shapes
/// `sandbox::exec` takes (`argv`, or `cmd` with `args`), else its path, and
/// what a write writes.
pub(crate) fn call_of(call: &Value) -> Call {
    let arguments = &call["arguments"];
    let words = |v: &Value| -> Vec<String> {
        v.as_array()
            .into_iter()
            .flatten()
            .filter_map(|w| w.as_str().map(String::from))
            .collect()
    };
    let mut line = words(&arguments["argv"]);
    if let Some(cmd) = arguments["cmd"].as_str() {
        line.push(cmd.into());
        line.extend(words(&arguments["args"]));
    }
    let text = if line.is_empty() {
        arguments["path"].as_str().unwrap_or_default().to_string()
    } else {
        line.join(" ")
    };
    Call {
        function: call["function_id"].as_str().unwrap_or_default().into(),
        text,
        content: arguments["content"].as_str().unwrap_or_default().into(),
    }
}

/// A call's arguments as a hook reads `tool_input`.
fn tool_input(held: &HeldCall) -> Value {
    match held.call.function.as_str() {
        "sandbox::exec" => json!({ "command": held.call.text }),
        _ => json!({ "file_path": held.call.text, "content": held.arguments["content"] }),
    }
}

fn text_result(text: &str, details: Value, is_error: bool) -> Value {
    json!({ "content": [{ "type": "text", "text": text }], "details": details, "is_error": is_error })
}

